class _FleetScreenState extends State<FleetScreen>{int tab=0;String q='';@override Widget build(BuildContext context){final s=context.watch<AppState>();final vs=s.vehicles;final idle=vs.where((v)=>v.status==VehicleStatus.idle).length;final moving=s.activeVehicles;final alert=vs.where((v)=>v.fuel<20||v.condition<55).length;return ListView(padding:const EdgeInsets.all(13),children:[Row(children:[Expanded(child:FilledButton(onPressed:()=>setState(()=>tab=0),style:FilledButton.styleFrom(backgroundColor:tab==0?AppColors.emerald:AppColors.surface,foregroundColor:tab==0?AppColors.background:AppColors.textPrimary),child:Text('Kendaraan • '+vs.length.toString()))),const SizedBox(width:7),Expanded(child:OutlinedButton(onPressed:()=>setState(()=>tab=1),child:const Text('Trailer • 0')))]),const SizedBox(height:9),FilledButton.icon(onPressed:()=>_dealership(context,s),icon:const Icon(Icons.add),label:const Text('Beli Armada')),const SizedBox(height:10),GridView.count(crossAxisCount:2,shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),childAspectRatio:2.6,mainAxisSpacing:7,crossAxisSpacing:7,children:[_metric('Kendaraan',vs.length.toString()+'/12'),_metric('Menganggur',idle.toString()),_metric('Dalam perjalanan',moving.toString()),_metric('Perhatian',alert.toString())]),const SizedBox(height:10),if(tab==0)TextField(onChanged:(v)=>setState(()=>q=v),decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Cari kendaraan'))else const Text('Belum ada trailer.',style:TextStyle(color:AppColors.textSecondary)),const SizedBox(height:10),if(tab==0)...vs.where((v)=>v.specifications.name.toLowerCase().contains(q.toLowerCase())).map((v)=>_vehicle(context,s,v))]);}
