Widget _vehicle(BuildContext c,AppState s,Vehicle v){final spec=v.specifications;final fuel=(v.fuel/spec.fuelCapacityLiters).clamp(0.0,1.0);return Container(margin:const EdgeInsets.only(bottom:10),padding:const EdgeInsets.all(12),decoration:BoxDecoration(color:AppColors.surface,borderRadius:BorderRadius.circular(14),border:Border.all(color:AppColors.border)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Text(spec.name,style:const TextStyle(fontWeight:FontWeight.w900))),Text(v.status==VehicleStatus.idle?'MENGANGGUR':'DALAM PERJALANAN',style:const TextStyle(color:AppColors.emerald,fontSize:8,fontWeight:FontWeight.w900))]),const SizedBox(height:9),Row(children:[const Icon(Icons.local_shipping,size:38,color:AppColors.emerald),const SizedBox(width:9),Expanded(child:Text('#'+v.vehicleId.substring(0,4).toUpperCase()+' • Box / Van • ban Standar\n'+spec.cargoCapacityKg.toStringAsFixed(0)+' kg • '+v.effectiveMaxSpeed.toStringAsFixed(0)+' km/j',style:const TextStyle(color:AppColors.textSecondary,fontSize:9))),IconButton(onPressed:()=>_service(c,s,v),icon:const Icon(Icons.build)),IconButton(onPressed:()=>s.setTab(1),icon:const Icon(Icons.my_location)),IconButton(onPressed:()=>s.showToast('Belum ada trailer.'),icon:const Icon(Icons.link))]),_bar('BBM',fuel,v.fuel.toStringAsFixed(1)+' L'),_bar('Kondisi',v.condition/100,v.condition.toStringAsFixed(0)+'%'),_bar('MASA PAKAI • BARU',1,'0 km / 500k km'),const Divider(),Row(children:[_info('SOPIR','Kamu'),_info('POSISI',s.company?.headquartersCity??'Markas'),_info('NILAI JUAL',GameFormatters.currency(v.estimatedValue))]),const SizedBox(height:7),Text('Parkir di '+(s.company?.headquartersCity??'Markas')+' • kendaraan Darat',style:const TextStyle(color:AppColors.textSecondary,fontSize:9))]));}
Widget _bar(String label,double value,String text)=>Padding(padding:const EdgeInsets.only(top:7),child:Column(children:[Row(children:[Expanded(child:Text(label,style:const TextStyle(color:AppColors.textSecondary,fontSize:9))),Text(text,style:const TextStyle(fontSize:9))]),LinearProgressIndicator(value:value.clamp(0.0,1.0),color:AppColors.emerald,backgroundColor:AppColors.border,minHeight:4)]));
